    stringToTimestamp(dateTimeString) {
      // 直接创建 Date 对象，假设输入格式正确
      const date = new Date(dateTimeString.replace(' ', 'T'));

      // 检查创建的 Date 是否有效
      if (isNaN(date.getTime())) {
