<template>
  <div class="container">
    <div class="player-container">
      <div id="playWnd" ref="playWnd">
      </div>
    </div>
  </div>
</template>

<script>
// import { listCamera } from "@/api/video/camera";
import { loadingJs } from './js/loadingJs.js';
import DomSize from "./js/domsize.js"
var oWebControl, initCount, pubKey;
var showDivInstruction = false;
var playWnd_width, playWnd_height;
export default {
  name: "Camera",
  data() {
    return {
      dialogVisible: false,
      // 遮罩层
      loading: true,
      // 是否显示弹出层
      open: false,
      filterText: '',
      cameraList: [
        {
          cameraName: '根节点',
          children: [],
        }
      ],
      // 查询参数
      queryParams: {
        pageNum: 1,
        pageSize: 200,
        deptId: null,
        installTypeCode: null,
        isUp: null,
        cameraName: null,
        isFocus: null,
      },
      currentVideo: null,
      defaultProps: {
        children: 'children',
        label: 'cameraName'
      },
      appkey: window.wgParameter.hkaf.appKey,
      ip: window.wgParameter.hkaf.ip,
      port: Number(window.wgParameter.hkaf.port),
      secret: window.wgParameter.hkaf.secret,
    };
  },
  watch: {
    filterText(val) {
      this.$refs.tree.filter(val);
    }
  },
  created() {
    console.log(window.wgParameter)
    // this.appkey = window.wgParameter.hkaf.appkey;
    // this.ip = window.wgParameter.hkaf.ip;
    // this.port = Number(window.wgParameter.hkaf.port);
    // this.secret = window.wgParameter.hkaf.secret;
    loadingJs('/static/build/hikplugin/web-control_1.2.5.min.js').then(() => {
      this.initPlugin();
    });
    loadingJs('/static/build/hikplugin/jsencrypt.min.js');
  },
  mounted() {
    // setTimeout(() => {
    //   this.start('724243b5966948bb905e5346a7409692')
    //   this.start('724243b5966948bb905e5346a7409692')
    //   this.start('724243b5966948bb905e5346a7409692')
    //   this.start('724243b5966948bb905e5346a7409692')
    // }, 3000);
  },
  methods: {
    initPlugin() {
      let that = this;
      let playWnddom = document.getElementById('playWnd');
      playWnd_width = playWnddom.getBoundingClientRect().width;
      playWnd_height = playWnddom.getBoundingClientRect().height;
      oWebControl = new WebControl({
        szPluginContainer: "playWnd",
        iServicePortStart: 15900,
        iServicePortEnd: 15900,
        szClassId: "23BF3B0A-2C56-4D97-9C03-0CB103AA8F11",   // 用于IE10使用ActiveX的clsid
        cbConnectSuccess: function () {
          initCount = 0;
          // setCallbacks();			
          oWebControl.JS_StartService("window", {
            dllPath: "./VideoPluginConnect.dll"
          }).then(function () {
            oWebControl.JS_CreateWnd("playWnd", playWnd_width, playWnd_height).then(function () {
              console.log("JS_CreateWnd success");
              oWebControl.JS_RequestInterface({
                funcName: "getRSAPubKey",
                argument: JSON.stringify({
                  keyLength: 1024
                })
              }).then(function (oData) {
                console.log(oData)
                if (oData.responseMsg.data) {
                  pubKey = oData.responseMsg.data
                }
                that.init();
              });
            });
          }, function () {

          });
        },
        cbConnectError: function () {
          console.log("cbConnectError");
          oWebControl = null;
          $("#playWnd").html("插件未启动，正在尝试启动，请稍候...");
          WebControl.JS_WakeUp("VideoWebPlugin://");
          initCount++;
          if (initCount < 3) {
            setTimeout(function () {
              initPlugin();
            }, 3000)
          } else {
            $("#playWnd").html("<span style='color:white'>插件启动失败，请检查插件是否安装！<span> <a id='uploadCJ' style='color:white;text-decoration: underline;'>下载插件</a>");
            $("#uploadCJ").click(() => {
              window.open("/static/VideoWebPlugin.exe");
            })
          }
        },
        cbConnectClose: function (bNormalClose) {
          // 异常断开：bNormalClose = false
          // JS_Disconnect正常断开：bNormalClose = true
          console.log("cbConnectClose");
          oWebControl = null;
          $("#playWnd").html("插件未启动，正在尝试启动，请稍候...");
          WebControl.JS_WakeUp("VideoWebPlugin://");
          initCount++;
          if (initCount < 3) {
            setTimeout(function () {
              initPlugin();
            }, 3000)
          } else {
            $("#playWnd").html("<span style='color:white'>插件启动失败，请检查插件是否安装！<span> <a id='uploadCJ' style='color:white;text-decoration: underline;'>下载插件</a>");
            $("#uploadCJ").click(() => {
              window.open("/static/VideoWebPlugin.exe");
            })
          }
        }
      });
      // $(window).resize(function () {
      //   let playWnddom = document.getElementById('playWnd');
      //   playWnd_width = playWnddom.getBoundingClientRect().width;
      //   playWnd_height = playWnddom.getBoundingClientRect().height;
      //     if (oWebControl != null) {
      //         oWebControl.JS_Resize(playWnd_width,playWnd_height);
      //         setWndCover();
      //     }
      // });
      DomSize.bind(that.$refs.playWnd, () => {
        let playWnddom = document.getElementById('playWnd');
        playWnd_width = playWnddom.getBoundingClientRect().width;
        playWnd_height = playWnddom.getBoundingClientRect().height;
        if (oWebControl != null) {
          oWebControl.JS_Resize(playWnd_width, playWnd_height);
          setWndCover();
        }
      });
      function setWndCover() {
        //获取web页面的尺寸
        var iWidth = $(window).width();
        var iHeight = $(window).height();
        //获取播放窗口div元素的左边界、右边界距离web页面左边界的长度、上边界、下边界距离web页面上边界的长度
        var oDivRect = $("#playWnd").get(0).getBoundingClientRect();
        //Math.round 为四舍五入    Math.abs 为取绝对值
        var iCoverLeft = (oDivRect.left < 0) ? Math.abs(oDivRect.left) : 0;
        var iCoverTop = (oDivRect.top < 0) ? Math.abs(oDivRect.top) : 0;
        var iCoverRight = (oDivRect.right - iWidth > 0) ? Math.round(oDivRect.right - iWidth) : 0;
        var iCoverBottom = (oDivRect.bottom - iHeight > 0) ? Math.round(oDivRect.bottom - iHeight) : 0;

        iCoverLeft = (iCoverLeft > playWnd_width) ? playWnd_width : iCoverLeft;
        iCoverTop = (iCoverTop > playWnd_height) ? playWnd_height : iCoverTop;
        iCoverRight = (iCoverRight > playWnd_width) ? playWnd_width : iCoverRight;
        iCoverBottom = (iCoverBottom > playWnd_height) ? playWnd_height : iCoverBottom;

        oWebControl.JS_RepairPartWindow(0, 0, playWnd_width + 1, playWnd_height);  // 多1个像素点防止还原后边界缺失一个像素条
        //抠除左边界
        if (iCoverLeft != 0) {
          oWebControl.JS_CuttingPartWindow(0, 0, iCoverLeft, playWnd_height + 1);
        }
        //抠除上边界
        if (iCoverTop != 0) {
          oWebControl.JS_CuttingPartWindow(0, 0, playWnd_width + 1, iCoverTop);  // 多剪掉一个像素条，防止出现剪掉一部分窗口后出现一个像素条
        }
        //抠除右边界
        if (iCoverRight != 0) {
          oWebControl.JS_CuttingPartWindow(playWnd_height + 1 - iCoverRight, 0, iCoverRight, playWnd_height + 1);
        }
        //抠除下边界
        if (iCoverBottom != 0) {
          oWebControl.JS_CuttingPartWindow(0, playWnd_height + 1 - iCoverBottom, playWnd_width + 1, iCoverBottom);
        }
        //弹框示例位置扣除
        if (showDivInstruction) {
          // 获取弹框的位置、尺寸信息
          var oDivLightRect = document.getElementById('light').getBoundingClientRect();

          iCoverLeft = (oDivLightRect.left - oDivRect.left < 0) ? 0 : oDivLightRect.left - oDivRect.left;
          iCoverTop = (oDivLightRect.top - oDivRect.top < 0) ? 0 : oDivLightRect.top - oDivRect.top;
          iCoverRight = (oDivLightRect.right - oDivRect.left < 0) ? 0 : oDivLightRect.right - oDivRect.left;
          iCoverBottom = (oDivLightRect.bottom - oDivRect.top < 0) ? 0 : oDivLightRect.bottom - oDivRect.top;

          iCoverLeft = (iCoverLeft > playWnd_width) ? playWnd_width : Math.round(iCoverLeft);
          iCoverTop = (iCoverTop > playWnd_height) ? playWnd_height : Math.round(iCoverTop);
          iCoverRight = (iCoverRight > playWnd_width) ? playWnd_width : Math.round(iCoverRight);
          iCoverBottom = (iCoverBottom > playWnd_height) ? playWnd_height : Math.round(iCoverBottom);

          //JS_CuttingPartWindow接口参照开发指南，参数为：抠图左上角点在插件窗口上的left长度、top长度、所扣除矩形区域的宽度、所扣除矩形区域的长度
          oWebControl.JS_CuttingPartWindow(iCoverLeft - 1, iCoverTop - 1, iCoverRight - iCoverLeft + 2, iCoverBottom - iCoverTop + 2);
        }
      }
      function setCallbacks() {
        oWebControl.JS_SetWindowControlCallback({
          cbIntegrationCallBack: cbIntegrationCallBack
        });
      }
      function cbIntegrationCallBack(oData) {
        showCBInfo(JSON.stringify(oData.responseMsg));
      }

    },
    // 加载插件
    init() {
      let JsonParam = {
        "argument": {
          "appkey": this.appkey,
          "ip": this.ip,
          "port": this.port,
          "secret": this.secret,
          "enableHTTPS": 1,
          "language": "zh_CN",
          "layout": "2x2",
          "playMode": 0,
          "reconnectDuration": 5,
          "reconnectTimes": 5,
          "showSmart": 0,
          "showToolbar": 1,
          "toolBarButtonIDs": "2048,2049,2050,2304,2306,2305,2307,2308,2309,4096,4608,4097,4099,4098,4609,4100",
          "snapDir": "D:/snap",
          "videoDir": "D:/video"
        },
        "funcName": "init"
      }
      oWebControl.JS_RequestInterface(JsonParam).then(function (oData) {
        console.log(oData)
        // showCBInfo(JSON.stringify(oData ? oData.responseMsg : ''));
        // UpdatePlayParamValue();
        oWebControl.JS_Resize(playWnd_width, playWnd_height);  // 
      });
    },
    /** 预览按钮操作 */
    // 实时视频播放函数
    start(id) {
      var JsonParam = {
        "argument": {
          // "authUuid": "",
          // "cameraIndexCode": id,
          // "ezvizDirect": 0,
          // "gpuMode": 0,
          // "streamMode": 0,
          // "transMode": 1,
          // "wndId": -1,
          // "cascade": 1
          "authUuid": "111",
          "cameraIndexCode": id,
          "ezvizDirect": 0,
          "gpuMode": 0,
          "streamMode": 0,
          "transMode": 1,
          "wndId": -1,
          "cascade": 1,
          "fontsize": 30,
          "transparent": 10,
          "rotateAngle": 60,
          "waterMark": "11111\n22222"
        },
        "funcName": "startPreview"
      }
      oWebControl.JS_RequestInterface(JsonParam)
    },
    // 回放视频播放函数
    backStart(id, start, end) {
      var JsonParam = {
        funcName: "startPlayback",
        argument: {
          cameraIndexCode: id, // 监控点编号
          startTimeStamp: start, // 录像查询开始时间戳，单位：秒
          endTimeStamp: end, // 录像查询结束时间戳，单位：秒
          recordLocation: 0, // 录像存储类型 0-中心存储 1-设备存储
          transMode: 1, // 传输协议 ，0-UDP 1-TCP
          gpuMode: 0 // 是否开启 GPU 硬解，0-不开启 1-开启
        }
      }
      oWebControl.JS_RequestInterface(JsonParam)
    },
    // 销毁插件
    destoryInit() {
      if (oWebControl) {
        oWebControl.JS_HideWnd();
        oWebControl.JS_RequestInterface({
          funcName: "destroyWnd"
        })
      }
    },
    // 设置布局
    setLayout(layout) {
      let JsonParam = {
        funcName: "setLayout",
        argument: {
          layout: layout // 窗口布局
        }
      }
      oWebControl.JS_RequestInterface(JsonParam)
    }
  },
  destroyed() {
    if (oWebControl) {
      oWebControl.JS_HideWnd();
      oWebControl.JS_RequestInterface({
        funcName: "destroyWnd"
      })
    }
  }
};
</script>
<style lang="scss" scoped>
.container {
  position: absolute;
  width: 100%;
  height: 100%;
  .player-container {
    height: 100%;
    width: 100%;
    #playWnd {
      width: 100%;
      height: 100%;
    }
  }
}
</style>